SELECT

FROM SYS_CLIENT
WHERE
LOGIC_DEL = 0

    AND CLIENT_ID = #{dto.clientId}


    AND CLIENT_KEY = #{dto.clientKey}


    AND CLIENT_SECRET = #{dto.clientSecret}


    AND GRANT_TYPE = #{dto.grantType}


    AND DEVICE_TYPE = #{dto.deviceType}


    AND ACTIVE_TIMEOUT = #{dto.activeTimeout}


    AND TIMEOUT = #{dto.timeout}

ORDER BY create_time DESC

